/**
 * Terrain by site id: a horizon worked out offline (`TERRAIN_HORIZONS`, generated by
 * scripts/data/horizon_profile.py) or a small height patch the app turns into one. The patches are
 * EMPTY ON PURPOSE: fill them only from a sourced DEM recorded in docs/DATA_SOURCES.md. Never add
 * made-up heights. Sites with neither keep the smooth-sphere horizon.
 */
import { TERRAIN_HORIZON_ENABLED } from '../app/featureFlags';
import { azimuthElevationOf, lunarSky, type LatLon } from '../utils/lunarSky';
import {
  horizonProfile,
  terrainIllumination,
  type GeneratedHorizon,
  type HorizonProfile,
  type TerrainIllumination,
  type TerrainPatch,
} from '../utils/terrainShadow';

type Horizons = Readonly<Record<string, HorizonProfile>>;

// The generated file is optional: TEST horizons stay on the laptop that made them (git-ignored)
// until their source is recorded, and the app works the same without them.
const generated = import.meta.glob<Readonly<Record<string, GeneratedHorizon>>>(
  './terrainHorizons.ts',
  {
    eager: true,
    import: 'TERRAIN_HORIZONS',
  },
);

/**
 * Horizons a build may use: all of them while developing, but never TEST ones (no recorded source)
 * in a production build, even if the local file happens to be there when it is built.
 */
export function usableHorizons<T extends { readonly source: string }>(
  horizons: Readonly<Record<string, T>>,
  production: boolean,
): Readonly<Record<string, T>> {
  if (!production) return horizons;
  return Object.fromEntries(
    Object.entries(horizons).filter(([, profile]) => !profile.source.startsWith('TEST')),
  );
}

/**
 * A generated horizon as the app uses it: the elevations as a Float32Array and, when the file has
 * it, `edgeCut` as a Uint8Array of 0/1 (number arrays and typed arrays are both accepted).
 */
export function toHorizonProfile(raw: GeneratedHorizon): HorizonProfile {
  const profile: HorizonProfile = {
    elevations:
      raw.elevations instanceof Float32Array ? raw.elevations : Float32Array.from(raw.elevations),
    radiusM: raw.radiusM,
    spacingM: raw.spacingM,
    source: raw.source,
  };
  if (raw.edgeCut) profile.edgeCut = Uint8Array.from(raw.edgeCut, (value) => (value ? 1 : 0));
  return profile;
}

export const TERRAIN_HORIZONS: Horizons = Object.fromEntries(
  Object.entries(usableHorizons(Object.values(generated)[0] ?? {}, import.meta.env.PROD)).map(
    ([siteId, raw]) => [siteId, toHorizonProfile(raw)],
  ),
);

export const TERRAIN_PATCHES: Readonly<Record<string, TerrainPatch>> = {};

const profiles = new Map<string, HorizonProfile | null>();

/**
 * The site's horizon profile (built once), or null when no terrain data is loaded for it, or the
 * terrain horizon is switched off (TERRAIN_HORIZON_ENABLED): then every place has the flat horizon.
 * `enabled` is for tests of the terrain code itself.
 */
export function terrainProfileFor(
  siteId: string,
  enabled: boolean = TERRAIN_HORIZON_ENABLED,
): HorizonProfile | null {
  if (!enabled) return null;
  if (!profiles.has(siteId)) {
    const ready = TERRAIN_HORIZONS[siteId];
    const patch = TERRAIN_PATCHES[siteId];
    profiles.set(siteId, ready ?? (patch ? horizonProfile(patch) : null));
  }
  return profiles.get(siteId) ?? null;
}

/** Whether terrain blocks the Sun at a site at a moment (UTC ms): the real Sun, the site's patch. */
export function sunTerrainAt(siteId: string, site: LatLon, ms: number): TerrainIllumination {
  const sun = azimuthElevationOf(lunarSky(new Date(ms)).sun, site);
  return terrainIllumination(terrainProfileFor(siteId), sun);
}
